Conditions:
∀ t ∈ tokenIds: pendingAssets[t] := pendingAssets[t] ∪ {assetId}
assetId > 0
replacesId ≥ 0

assetId ∈ pendingAssets[tokenId]
pendingAssets[tokenId] := pendingAssets[tokenId] \ {assetId}
activeAssets[tokenId] := activeAssets[tokenId] ∪ {assetId}
(replacesId = 0) ∨ ( replacesId ∈ activeAssets[tokenId] ∧ activeAssets[tokenId] := activeAssets[tokenId] \ {replacesId} )
auth(msg.sender, tokenId)

(assetId = 0) ∨ (assetId ∈ pendingAssets[tokenId])
pendingAssets[tokenId] := if assetId = 0 then ∅ else pendingAssets[tokenId] \ {assetId}
auth(msg.sender, tokenId)

(childAddress, childId) ∈ pendingChildren[tokenId]
pendingChildren[tokenId] := pendingChildren[tokenId] \ {(childAddress, childId)}
activeChildren[tokenId] := activeChildren[tokenId] ∪ {(childAddress, childId)}
auth(msg.sender, tokenId)
